                        VALUES (
                            588,
                            'Art. 148',
                            'Qualquer que seja a decisão, não fará coisa julgada em prejuízo de ulterior processo
penal ou civil.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
