INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            652,
                            'Art. 206',
                            'A testemunha não poderá eximir-se da obrigação de depor. Poderão, entretanto,
recusar-se a fazê-lo o ascendente ou descendente, o afim em linha reta, o cônjuge, ainda que
desquitado, o irmão e o pai, a mãe, ou o filho adotivo do acusado, salvo quando não for possível,
por outro modo, obter-se ou integrar-se a prova do fato e de suas circunstâncias.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO I – DO PROCESSO EM GERAL
TÍTULO VII – DA PROVA
CAPÍTULO VI – DAS TESTEMUNHAS',
                            'CÓDIGO DE PROCESSO PENAL'
                        );

