                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            665,
                            'Art. 219',
                            'O juiz poderá aplicar à testemunha faltosa a multa prevista no artigo 453, sem prejuízo do processo penal por crime de desobediência, e condená-la ao pagamento das custas da
diligência. (Artigo com redação dada pela Lei nº 6.416, de 24/5/1977)',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO I – DO PROCESSO EM GERAL
TÍTULO VII – DA PROVA
CAPÍTULO VI – DAS TESTEMUNHAS',
                            'CÓDIGO DE PROCESSO PENAL'
                        );

INSERT INTO CODIGOPENAL (
