INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            705,
                            'Art. 258',
                            'Os órgãos do Ministério Público não funcionarão nos processos em que o juiz ou qualquer das partes for seu cônjuge, ou parente, consanguíneo ou afim, em linha reta ou colateral,
até o terceiro grau, inclusive, e a eles se estendem, no que lhes for aplicável, as prescrições
relativas à suspeição e aos impedimentos dos juízes.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO I – DO PROCESSO EM GERAL
