                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            788,
                            'Art. 338',
                            'A fiança que se reconheça não ser cabível na espécie será cassada em qualquer fase
do processo.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
