INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            789,
                            'Art. 339',
                            'Será também cassada a fiança quando reconhecida a existência de delito inafiançável,
no caso de inovação na classificação do delito.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
