INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            802,
                            'Art. 352',
                            'O mandado de citação indicará:
I – o nome do juiz;
II – o nome do querelante nas ações iniciadas por queixa;
III – o nome do réu, ou, se for desconhecido, os seus sinais característicos;
IV – a residência do réu, se for conhecida;
V – o fim para que é feita a citação;
VI – o juízo e o lugar, o dia e a hora em que o réu deverá comparecer;
VII – a subscrição do escrivão e a rubrica do juiz.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO I – DO PROCESSO EM GERAL
TÍTULO X – DAS CITAÇÕES E INTIMAÇÕES
CAPÍTULO I – DAS CITAÇÕES',
                            'CÓDIGO DE PROCESSO PENAL'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            803,
                            'Art. 353',
                            'Quando o réu estiver fora do território da jurisdição do juiz processante, será citado
mediante precatória.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO I – DO PROCESSO EM GERAL
TÍTULO X – DAS CITAÇÕES E INTIMAÇÕES
CAPÍTULO I – DAS CITAÇÕES',
                            'CÓDIGO DE PROCESSO PENAL'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            804,
                            'Art. 354',
                            'A precatória indicará:
I – o juiz deprecado e o juiz deprecante;
II – a sede da jurisdição de um e de outro;
III – o fim para que é feita a citação, com todas as especificações;
IV – o juízo do lugar, o dia e a hora em que o réu deverá comparecer.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO I – DO PROCESSO EM GERAL
TÍTULO X – DAS CITAÇÕES E INTIMAÇÕES
CAPÍTULO I – DAS CITAÇÕES',
                            'CÓDIGO DE PROCESSO PENAL'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            805,
                            'Art. 355',
                            'A precatória será devolvida ao juiz deprecante, independentemente de traslado, depois de lançado o “cumpra-se” e de feita a citação por mandado do juiz deprecado.
§ 1º Verificado que o réu se encontra em território sujeito à jurisdição de outro juiz, a este
remeterá o juiz deprecado os autos para efetivação da diligência, desde que haja tempo para
fazer-se a citação.
§ 2º Certificado pelo oficial de justiça que o réu se oculta para não ser citado, a precatória
será imediatamente devolvida, para o fim previsto no art. 362.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO I – DO PROCESSO EM GERAL
TÍTULO X – DAS CITAÇÕES E INTIMAÇÕES
CAPÍTULO I – DAS CITAÇÕES',
                            'CÓDIGO DE PROCESSO PENAL'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            806,
                            'Art. 356',
                            'Se houver urgência, a precatória, que conterá em resumo os requisitos enumerados
no art. 354, poderá ser expedida por via telegráfica, depois de reconhecida a firma do juiz, o que
a estação expedidora mencionará.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO I – DO PROCESSO EM GERAL
TÍTULO X – DAS CITAÇÕES E INTIMAÇÕES
CAPÍTULO I – DAS CITAÇÕES',
                            'CÓDIGO DE PROCESSO PENAL'
                        );

