INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            841,
                            'Art. 391',
                            'O querelante ou o assistente será intimado da sentença, pessoalmente ou na pessoa
de seu advogado. Se nenhum deles for encontrado no lugar da sede do juízo, a intimação será
feita mediante edital com o prazo de 10 dias, afixado no lugar do costume.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO I – DO PROCESSO EM GERAL
TÍTULO XII – DA SENTENÇA',
                            'CÓDIGO DE PROCESSO PENAL'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            842,
                            'Art. 392',
                            'A intimação da sentença será feita:
I – ao réu, pessoalmente, se estiver preso;
II – ao réu, pessoalmente, ou ao defensor por ele constituído, quando se livrar solto, ou,
sendo afiançável a infração, tiver prestado fiança;
III – ao defensor constituído pelo réu, se este, afiançável, ou não, a infração, expedido o
mandado de prisão, não tiver sido encontrado, e assim o certificar o oficial de justiça;
IV – mediante edital, nos casos do nº II, se o réu e o defensor que houver constituído não
forem encontrados, e assim o certificar o oficial de justiça;
V – mediante edital, nos casos do nº III, se o defensor que o réu houver constituído também
não for encontrado, e assim o certificar o oficial de justiça;
VI – mediante edital, se o réu, não tendo constituído defensor, não for encontrado, e assim
o certificar o oficial de justiça.
§ 1º O prazo do edital será de 90 dias, se tiver sido imposta pena privativa de liberdade por
tempo igual ou superior a um ano, e de 60 dias, nos outros casos.
§ 2º O prazo para apelação correrá após o término do fixado no edital, salvo se, no curso
deste, for feita a intimação por qualquer das outras formas estabelecidas neste artigo.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO I – DO PROCESSO EM GERAL
TÍTULO XII – DA SENTENÇA',
                            'CÓDIGO DE PROCESSO PENAL'
                        );

