                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            920,
                            'Art. 467',
                            'Verificando que se encontram na urna as cédulas relativas aos jurados presentes, o
juiz presidente sorteará 7 (sete) dentre eles para a formação do Conselho de Sentença. (Artigo
com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
