                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            975,
                            'Art. 530-F',
                            'Ressalvada a possibilidade de se preservar o corpo de delito, o juiz poderá determinar, a requerimento da vítima, a destruição da produção ou reprodução apreendida quando não
houver impugnação quanto à sua ilicitude ou quando a ação penal não puder ser iniciada por
falta de determinação de quem seja o autor do ilícito. (Artigo acrescido pela Lei nº 10.695, de 1º/7/2003,
publicada no DOU de 2/7/2003, em vigor 30 dias após a publicação)',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
