INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1060,
                            'Art. 617',
                            'O tribunal, câmara ou turma atenderá nas suas decisões ao disposto nos arts. 383,
386 e 387, no que for aplicável, não podendo, porém, ser agravada a pena, quando somente o
réu houver apelado da sentença.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
