INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1189,
                            'Art. 751',
                            'Durante a execução da pena ou durante o tempo em que a ela se furtar o condenado,
poderá ser imposta medida de segurança, se:
I – o juiz ou o tribunal, na sentença:
a) omitir sua decretação, nos casos de periculosidade presumida;
b) deixar de aplicá-la ou de excluí-la expressamente;
c) declarar os elementos constantes do processo insuficientes para a imposição ou exclusão
da medida e ordenar indagações para a verificação da periculosidade do condenado;
II – tendo sido, expressamente, excluída na sentença a periculosidade do condenado, novos
fatos demonstrarem ser ele perigoso.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO IV – DA EXECUÇÃO
TÍTULO V – DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA',
                            'CÓDIGO DE PROCESSO PENAL'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1190,
                            'Art. 752',
                            'Poderá ser imposta medida de segurança, depois de transitar em julgado a sentença,
ainda quando não iniciada a execução da pena, por motivo diverso de fuga ou ocultação do
condenado:
I – no caso da letra a do nº I do artigo anterior, bem como no da letra b, se tiver sido alegada
a periculosidade;
II – no caso da letra c do nº I do mesmo artigo.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO IV – DA EXECUÇÃO
TÍTULO V – DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA',
                            'CÓDIGO DE PROCESSO PENAL'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1191,
                            'Art. 753',
                            'Ainda depois de transitar em julgado a sentença absolutória, poderá ser imposta a
medida de segurança, enquanto não decorrido tempo equivalente ao da sua duração mínima,
a indivíduo que a lei presuma perigoso.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
LIVRO IV – DA EXECUÇÃO
TÍTULO V – DA EXECUÇÃO DAS MEDIDAS DE SEGURANÇA',
                            'CÓDIGO DE PROCESSO PENAL'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1192,
                            'Art. 754',
                            'A aplicação da medida de segurança, nos casos previstos nos arts. 751 e 752, competirá ao juiz da execução da pena, e, no caso do art. 753, ao juiz da sentença.',
                            'DECRETO-LEI Nº 3.689, DE 3 DE OUTUBRO DE 1941
(CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/10/1941 e retificado no DOU de 24/10/1941)
