INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1269,
                            'Artigo 19',
                            'Direitos da criança
Toda criança tem direito às medidas de proteção que a sua condição de menor requer por
parte da sua família, da sociedade e do Estado.',
                            'CONVENÇÃO AMERICANA SOBRE DIREITOS HUMANOS (PACTO DE SÃO JOSÉ DA COSTA RICA, 1969)
