INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1315,
                            'Artigo 65',
                            'A Corte submeterá à consideração da Assembleia-Geral da Organização, em cada período
ordinário de sessões, um relatório sobre suas atividades no ano anterior. De maneira especial,
e com as recomendações pertinentes, indicará os casos em que um Estado não tenha dado
cumprimento a suas sentenças.',
