INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1317,
                            'Artigo 67',
                            'A sentença da Corte será definitiva e inapelável. Em caso de divergência sobre o sentido
ou alcance da sentença, a Corte interpretá-la-á, a pedido de qualquer das partes, desde que
o pedido seja apresentado dentro de noventa dias a partir da data da notificação da sentença.',
                            'CONVENÇÃO AMERICANA SOBRE DIREITOS HUMANOS (PACTO DE SÃO JOSÉ DA COSTA RICA, 1969)
