INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1372,
                            'Art. 13',
                            'A aplicação da lei nova a fato julgado por sentença condenatória irrecorrível, nos casos
previstos no art. 2º e seu parágrafo, do Código Penal, far-se-á mediante despacho do juiz, de
ofício, ou a requerimento do condenado ou do Ministério Público.
§ 1º Do despacho caberá recurso, em sentido estrito.
§ 2º O recurso interposto pelo Ministério Público terá efeito suspensivo, no caso de condenação por crime a que a lei anterior comine, no máximo, pena privativa de liberdade, por
tempo igual ou superior a oito anos.',
                            'DECRETO-LEI Nº 3.931, DE 11 DE DEZEMBRO DE 1941
(LEI DE INTRODUÇÃO AO CÓDIGO DE PROCESSO PENAL)
(Publicado no DOU de 13/12/1941)',
                            'LEI DE INTRODUÇÃO AO CÓDIGO DE PROCESSO PENAL'
                        );

INSERT INTO CODIGOPENAL (
