INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1568,
                            'Art. 114',
                            'Somente poderá ingressar no regime aberto o condenado que:
I – estiver trabalhando ou comprovar a possibilidade de fazê-lo imediatamente;
II – apresentar, pelos seus antecedentes ou pelo resultado dos exames a que foi submetido,
fundados indícios de que irá ajustar-se, com autodisciplina e senso de responsabilidade, ao
novo regime.
Parágrafo único. Poderão ser dispensadas do trabalho as pessoas referidas no art. 117
desta Lei.',
                            'LEI Nº 7.210, DE 11 DE JULHO DE 1984
(LEI DE EXECUÇÃO PENAL)
(Publicada no DOU de 13/7/1984)
TÍTULO V – DA EXECUÇÃO DAS PENAS EM ESPÉCIE
CAPÍTULO I – DAS PENAS PRIVATIVAS DE LIBERDADE
Seção II – Dos Regimes',
                            'LEI DE EXECUÇÃO PENAL'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1569,
                            'Art. 115',
                            'O juiz poderá estabelecer condições especiais para a concessão de regime aberto,
sem prejuízo das seguintes condições gerais e obrigatórias:
I – permanecer no local que for designado, durante o repouso e nos dias de folga;
II – sair para o trabalho e retornar, nos horários fixados;
III – não se ausentar da cidade onde reside, sem autorização judicial;
IV – comparecer a juízo, para informar e justificar as suas atividades, quando for determinado.',
                            'LEI Nº 7.210, DE 11 DE JULHO DE 1984
(LEI DE EXECUÇÃO PENAL)
(Publicada no DOU de 13/7/1984)
TÍTULO V – DA EXECUÇÃO DAS PENAS EM ESPÉCIE
CAPÍTULO I – DAS PENAS PRIVATIVAS DE LIBERDADE
Seção II – Dos Regimes',
                            'LEI DE EXECUÇÃO PENAL'
                        );

