INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1574,
                            'Art. 120',
                            'Os condenados que cumprem pena em regime fechado ou semiaberto e os presos
provisórios poderão obter permissão para sair do estabelecimento, mediante escolta, quando
ocorrer um dos seguintes fatos:
I – falecimento ou doença grave do cônjuge, companheira, ascendente, descendente ou irmão;
II – necessidade de tratamento médico (parágrafo único do art. 14).
Parágrafo único. A permissão de saída será concedida pelo diretor do estabelecimento onde
se encontra o preso.',
                            'LEI Nº 7.210, DE 11 DE JULHO DE 1984
(LEI DE EXECUÇÃO PENAL)
(Publicada no DOU de 13/7/1984)
TÍTULO V – DA EXECUÇÃO DAS PENAS EM ESPÉCIE
CAPÍTULO I – DAS PENAS PRIVATIVAS DE LIBERDADE
Seção III – Das Autorizações de Saída
Subseção I – Da Permissão de Saída',
                            'LEI DE EXECUÇÃO PENAL'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1575,
                            'Art. 121',
                            'A permanência do preso fora do estabelecimento terá a duração necessária à finalidade da saída.',
                            'LEI Nº 7.210, DE 11 DE JULHO DE 1984
(LEI DE EXECUÇÃO PENAL)
(Publicada no DOU de 13/7/1984)
TÍTULO V – DA EXECUÇÃO DAS PENAS EM ESPÉCIE
CAPÍTULO I – DAS PENAS PRIVATIVAS DE LIBERDADE
Seção III – Das Autorizações de Saída
Subseção I – Da Permissão de Saída',
