                        VALUES (
                            1684,
                            'Art. 20-A',
                            'Os crimes previstos nesta Lei terão as penas aumentadas de 1/3 (um terço) até a metade, quando ocorrerem em contexto ou com intuito de descontração, diversão ou recreação.
(Artigo acrescido pela Lei nº 14.532, de 11/1/2023)',
                            'LEI Nº 7.716, DE 5 DE JANEIRO DE 1989
(LEI CAÓ)
(Publicada no DOU de 6/1/1989 e retificada no DOU de 9/1/1989)',
                            'LEI CAÓ'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1685,
                            'Art. 20-B',
                            'Os crimes previstos nos arts. 2º-A e 20 desta Lei terão as penas aumentadas de 1/3
(um terço) até a metade, quando praticados por funcionário público, conforme definição prevista no Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), no exercício de suas
funções ou a pretexto de exercê-las. (Artigo acrescido pela Lei nº 14.532, de 11/1/2023)',
                            'LEI Nº 7.716, DE 5 DE JANEIRO DE 1989
(LEI CAÓ)
(Publicada no DOU de 6/1/1989 e retificada no DOU de 9/1/1989)',
                            'LEI CAÓ'
                        );

