INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1704,
                            'Art. 8',
                            'Será de três a seis anos de reclusão a pena prevista no art. 288 do Código Penal, quando
se tratar de crimes hediondos, prática da tortura, tráfico ilícito de entorpecentes e drogas afins
ou terrorismo.
Parágrafo único. O participante e o associado que denunciar à autoridade o bando ou quadrilha, possibilitando seu desmantelamento, terá a pena reduzida de um a dois terços.',
                            'LEI Nº 8.072, DE 25 DE JULHO DE 1990
(LEI DOS CRIMES HEDIONDOS)
(Publicada no DOU de 26/7/1990)',
                            'LEI DOS CRIMES HEDIONDOS'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1705,
                            'Art. 9',
                            'As penas fixadas no art. 6º para os crimes capitulados nos arts. 157, § 3º, 158, § 2º, 159,
caput e seus §§ 1º, 2º e 3º, 213, caput, e sua combinação com o art. 223, caput e parágrafo único,
214 e sua combinação com o art. 223, caput e parágrafo único, todos do Código Penal, são
acrescidas de metade, respeitado o limite superior de trinta anos de reclusão, estando a vítima
em qualquer das hipóteses referidas no art. 224 também do Código Penal.',
                            'LEI Nº 8.072, DE 25 DE JULHO DE 1990
(LEI DOS CRIMES HEDIONDOS)
(Publicada no DOU de 26/7/1990)',
                            'LEI DOS CRIMES HEDIONDOS'
                        );

