INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1892,
                            'Art. 18',
                            'Constituem atividades de prevenção do uso indevido de drogas, para efeito desta Lei,
aquelas direcionadas para a redução dos fatores de vulnerabilidade e risco e para a promoção
e o fortalecimento dos fatores de proteção.',
                            'LEI Nº 11.343, DE 23 DE AGOSTO DE 2006
(LEI DE DROGAS)
(Publicada no DOU de 24/8/2006)
TÍTULO III – DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS
CAPÍTULO I – DA PREVENÇÃO
Seção I – Das Diretrizes',
                            'LEI DE DROGAS'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1893,
                            'Art. 19',
                            'As atividades de prevenção do uso indevido de drogas devem observar os seguintes
princípios e diretrizes:
I – o reconhecimento do uso indevido de drogas como fator de interferência na qualidade
de vida do indivíduo e na sua relação com a comunidade à qual pertence;
II – a adoção de conceitos objetivos e de fundamentação científica como forma de orientar
as ações dos serviços públicos comunitários e privados e de evitar preconceitos e estigmatização das pessoas e dos serviços que as atendam;
III – o fortalecimento da autonomia e da responsabilidade individual em relação ao uso
indevido de drogas;
IV – o compartilhamento de responsabilidades e a colaboração mútua com as instituições
do setor privado e com os diversos segmentos sociais, incluindo usuários e dependentes de
drogas e respectivos familiares, por meio do estabelecimento de parcerias;
V – a adoção de estratégias preventivas diferenciadas e adequadas às especificidades socioculturais das diversas populações, bem como das diferentes drogas utilizadas;
VI – o reconhecimento do “não uso”, do “retardamento do uso” e da redução de riscos como
resultados desejáveis das atividades de natureza preventiva, quando da definição dos objetivos a serem alcançados;
VII – o tratamento especial dirigido às parcelas mais vulneráveis da população, levando em
consideração as suas necessidades específicas;
VIII – a articulação entre os serviços e organizações que atuam em atividades de prevenção
do uso indevido de drogas e a rede de atenção a usuários e dependentes de drogas e respectivos familiares;
IX – o investimento em alternativas esportivas, culturais, artísticas, profissionais, entre outras, como forma de inclusão social e de melhoria da qualidade de vida;
X – o estabelecimento de políticas de formação continuada na área da prevenção do uso
indevido de drogas para profissionais de educação nos 3 (três) níveis de ensino;
XI – a implantação de projetos pedagógicos de prevenção do uso indevido de drogas, nas
instituições de ensino público e privado, alinhados às Diretrizes Curriculares Nacionais e aos
conhecimentos relacionados a drogas;
XII – a observância das orientações e normas emanadas do Conad;
XIII – o alinhamento às diretrizes dos órgãos de controle social de políticas setoriais
específicas.
Parágrafo único. As atividades de prevenção do uso indevido de drogas dirigidas à criança
e ao adolescente deverão estar em consonância com as diretrizes emanadas pelo Conselho
Nacional dos Direitos da Criança e do Adolescente (Conanda).',
                            'LEI Nº 11.343, DE 23 DE AGOSTO DE 2006
(LEI DE DROGAS)
(Publicada no DOU de 24/8/2006)
TÍTULO III – DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS
CAPÍTULO I – DA PREVENÇÃO
Seção I – Das Diretrizes',
                            'LEI DE DROGAS'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1894,
                            'Art. 19-A',
                            'Fica instituída a Semana Nacional de Políticas sobre Drogas, comemorada anualmente, na quarta semana de junho.
§ 1º No período de que trata o caput, serão intensificadas as ações de:
I – difusão de informações sobre os problemas decorrentes do uso de drogas;
II – promoção de eventos para o debate público sobre as políticas sobre drogas;
III – difusão de boas práticas de prevenção, tratamento, acolhimento e reinserção social e
econômica de usuários de drogas;
IV – divulgação de iniciativas, ações e campanhas de prevenção do uso indevido de drogas;
V – mobilização da comunidade para a participação nas ações de prevenção e enfrentamento às drogas;
VI – mobilização dos sistemas de ensino previstos na Lei nº 9.394, de 20 de dezembro de
1996 (Lei de Diretrizes e Bases da Educação Nacional), na realização de atividades de prevenção
ao uso de drogas. (Artigo acrescido pela Lei nº 13.840, de 5/6/2019)',
                            'LEI Nº 11.343, DE 23 DE AGOSTO DE 2006
(LEI DE DROGAS)
(Publicada no DOU de 24/8/2006)
TÍTULO III – DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS
CAPÍTULO I – DA PREVENÇÃO
Seção II – Da Semana Nacional de Políticas sobre Drogas',
                            'LEI DE DROGAS'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1895,
                            'Art. 20',
                            'Constituem atividades de atenção ao usuário e dependente de drogas e respectivos
familiares, para efeito desta Lei, aquelas que visem à melhoria da qualidade de vida e à redução
dos riscos e dos danos associados ao uso de drogas.',
                            'LEI Nº 11.343, DE 23 DE AGOSTO DE 2006
(LEI DE DROGAS)
(Publicada no DOU de 24/8/2006)
TÍTULO III – DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS
CAPÍTULO II – DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS
Seção I – Disposições Gerais',
                            'LEI DE DROGAS'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1896,
                            'Art. 21',
                            'Constituem atividades de reinserção social do usuário ou do dependente de drogas
e respectivos familiares, para efeito desta Lei, aquelas direcionadas para sua integração ou
reintegração em redes sociais.',
                            'LEI Nº 11.343, DE 23 DE AGOSTO DE 2006
(LEI DE DROGAS)
(Publicada no DOU de 24/8/2006)
TÍTULO III – DAS ATIVIDADES DE PREVENÇÃO DO USO INDEVIDO, ATENÇÃO E REINSERÇÃO SOCIAL DE USUÁRIOS E DEPENDENTES DE DROGAS
CAPÍTULO II – DAS ATIVIDADES DE PREVENÇÃO, TRATAMENTO, ACOLHIMENTO E DE REINSERÇÃO SOCIAL E ECONÔMICA DE USUÁRIOS OU DEPENDENTES DE DROGAS
Seção I – Disposições Gerais',
                            'LEI DE DROGAS'
                        );

INSERT INTO CODIGOPENAL (
                            id,
                            Artigo,
                            DescricaoArtigo,
                            TituloLei,
                            TipoLei
                        )
                        VALUES (
                            1897,
                            'Art. 22',
                            'As atividades de atenção e as de reinserção social do usuário e do dependente de
drogas e respectivos familiares devem observar os seguintes princípios e diretrizes:
I – respeito ao usuário e ao dependente de drogas, independentemente de quaisquer condições, observados os direitos fundamentais da pessoa humana, os princípios e diretrizes do
Sistema Único de Saúde e da Política Nacional de Assistência Social;
II – a adoção de estratégias diferenciadas de atenção e reinserção social do usuário e do
dependente de drogas e respectivos familiares que considerem as suas peculiaridades socioculturais;
III – definição de projeto terapêutico individualizado, orientado para a inclusão social e para
a redução de riscos e de danos sociais e à saúde;
IV – atenção ao usuário ou dependente de drogas e aos respectivos familiares, sempre que
possível, de forma multidisciplinar e por equipes multiprofissionais;
V – observância das orientações e normas emanadas do Conad;
VI – o alinhamento às diretrizes dos órgãos de controle social de políticas setoriais específicas;
VII – estímulo à capacitação técnica e profissional; (Inciso acrescido pela Lei nº 13.840, de 5/6/2019)
VIII – efetivação de políticas de reinserção social voltadas à educação continuada e ao trabalho; (Inciso acrescido pela Lei nº 13.840, de 5/6/2019)
IX – observância do plano individual de atendimento na forma do art. 23-B desta Lei; (Inciso
acrescido pela Lei nº 13.840, de 5/6/2019)
X – orientação adequada ao usuário ou dependente de drogas quanto às consequências
lesivas do uso de drogas, ainda que ocasional. (Inciso acrescido pela Lei nº 13.840, de 5/6/2019)',
                            'LEI Nº 11.343, DE 23 DE AGOSTO DE 2006
(LEI DE DROGAS)
(Publicada no DOU de 24/8/2006)
